import{_ as a,o as e,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Performance Meeting 2021-06-10","description":"","frontmatter":{"title":"Ceph Performance Meeting 2021-06-10","date":"2021-06-10T00:00:00.000Z","updated":"2021-06-11T00:00:00.000Z","tags":["Ceph","性能分析","RGW","OSD内存目标","TC Malloc"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Performance_Meeting_2021-06-10.md","filePath":"posts/2021/Ceph_Performance_Meeting_2021-06-10.md","lastUpdated":1780459816000}'),r={name:"posts/2021/Ceph_Performance_Meeting_2021-06-10.md"};function o(n,l,s,c,h,u){return e(),i("div",null,[...l[0]||(l[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph性能对比分析及问题讨论" tabindex="-1">会议主题：Ceph性能对比分析及问题讨论 <a class="header-anchor" href="#会议主题-ceph性能对比分析及问题讨论" aria-label="Permalink to &quot;会议主题：Ceph性能对比分析及问题讨论&quot;">​</a></h4><h4 id="参会人员-mark-缺席-、其他相关人员" tabindex="-1">参会人员：Mark（缺席）、其他相关人员 <a class="header-anchor" href="#参会人员-mark-缺席-、其他相关人员" aria-label="Permalink to &quot;参会人员：Mark（缺席）、其他相关人员&quot;">​</a></h4><h4 id="会议时间-待定" tabindex="-1">会议时间：待定 <a class="header-anchor" href="#会议时间-待定" aria-label="Permalink to &quot;会议时间：待定&quot;">​</a></h4><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><p><strong>Ceph性能对比分析</strong>：</p><ul><li>对比了Nautilus和Pacific版本在RGW工作负载下的性能。</li><li>使用了两种不同的工作负载：一种是针对较小对象（1KB至256KB）的cost bench，另一种是混合小对象和大对象（最大1GB）的gauss bench。</li><li>发现Pacific在处理小对象工作负载时性能优于Nautilus，但在处理混合对象工作负载时性能不如Nautilus。</li></ul></li><li><p><strong>问题分析与讨论</strong>：</p><ul><li><strong>OSD内存目标设置问题</strong>： <ul><li>在Pacific版本中，OSD内存目标未被任何部署方法覆盖，特别是cephadm无法覆盖OSD内存目标。</li><li>Nautilus版本中，OSD内存目标应根据主机内存自动计算，但实际上实验中使用的内存远低于预期。</li></ul></li><li><strong>TC Malloc环境变量设置问题</strong>： <ul><li>讨论了TC Malloc环境变量（PC Malloc Max Total Thread Cache Bytes）的设置问题，发现即使在Nautilus中，该变量也未正确设置。</li><li>提出了两个相关的PR来解决这个问题，一个是全局设置，另一个是通过优先级缓存管理器设置。</li></ul></li></ul></li><li><p><strong>后续行动计划</strong>：</p><ul><li>重新进行实验以验证结果，特别是Nautilus版本的实验。</li><li>确保TC Malloc环境变量正确设置，并考虑是否需要动态调整。</li><li>讨论是否将相关更改回溯到Pacific版本。</li></ul></li></ol><h4 id="其他讨论" tabindex="-1">其他讨论： <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论：&quot;">​</a></h4><ul><li>Mark原计划讨论RBD测试和RGW的MTP使用情况，但由于缺席，推迟到下次会议。</li><li>确认了TC Malloc的灵活性，并讨论了动态调整的可能性。</li></ul><h4 id="后续会议" tabindex="-1">后续会议： <a class="header-anchor" href="#后续会议" aria-label="Permalink to &quot;后续会议：&quot;">​</a></h4><ul><li>下次会议将继续讨论RBD测试和RGW的MTP使用情况。</li><li>确认是否有其他议题需要讨论。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>会议在无其他议题讨论的情况下结束，感谢所有参与者的贡献。</li></ul><p><strong>备注</strong>：会议中提到的关键术语和工具包括：</p><ul><li><strong>Ceph</strong>：分布式存储系统。</li><li><strong>RGW</strong>：Ceph的对象网关。</li><li><strong>OSD</strong>：Object Storage Daemon，Ceph的存储守护进程。</li><li><strong>TC Malloc</strong>：线程缓存malloc，一种内存分配器。</li><li><strong>cephadm</strong>：Ceph的部署和管理工具。</li><li><strong>PR</strong>：Pull Request，代码贡献的一种形式。</li></ul><p><strong>行动项</strong>：</p><ul><li>重新进行Nautilus版本的实验。</li><li>确保TC Malloc环境变量正确设置。</li><li>考虑回溯相关更改到Pacific版本。</li><li>动态调整TC Malloc设置的可能性。</li></ul>',16)])])}const g=a(r,[["render",o]]);export{d as __pageData,g as default};
